package cn.whu.gaoshan.core;
import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;import java.io.*;import javax.sound.midi.*;
public final class PerformanceTests {
 static int checks;static void check(boolean b,String text){checks++;if(!b)throw new AssertionError(text);}
 interface Job{void run()throws Exception;}static void fails(Job j)throws Exception{try{j.run();throw new AssertionError("expected rejection");}catch(IllegalArgumentException|IOException expected){checks++;}}
 static PerformanceRecording fixture(int n,boolean overlap,boolean longNote){byte[] bytes=new byte[n*12];for(int k=0;k<n;k++){int i=k*12;Wire.put32(bytes,i,overlap?0:k*10);Wire.put32(bytes,i+4,longNote?70000:overlap?500:5);bytes[i+8]=(byte)(k%2==0?21:108);bytes[i+9]=(byte)(k%127+1);bytes[i+10]=(byte)(k%16);bytes[i+11]=(byte)(k%36);}byte[] status=new byte[20];status[1]=5;Wire.put32(status,2,88);Wire.put16(status,6,n);Wire.put32(status,8,3600000);Wire.put32(status,12,Wire.crc32(bytes));PerformanceRecording r=new PerformanceRecording(new ProtocolClient.RecordingStatus(status));System.arraycopy(bytes,0,r.data,0,bytes.length);r.received=n;return r;}
 public static void main(String[] args)throws Exception{
  ProtocolClient old=new ProtocolClient(new SimulatedDevice());old.hello();check(!old.performanceCapabilities(),"old firmware fallback");fails(()->old.readKeyMap());
  SimulatedDevice peer=new SimulatedDevice(true);ProtocolClient client=new ProtocolClient(peer);client.hello();check(client.performanceCapabilities(),"caps");KeyMap map=client.readKeyMap();check(Arrays.equals(map.bytes,KeyMap.defaults().bytes),"default map");
  map=map.with(0,21,0).with(1,21,15).with(35,108,31);final KeyMap finalMap=map;
  peer.dropCommand=0x53;peer.dropCount=1;client.applyKeyMap(map);check(Arrays.equals(map.bytes,client.readKeyMap().bytes),"mapping retry");
  int job=client.saveKeyMap(map);ProtocolClient.KeyMapStatus ks=client.keyMapStatus();check(ks.job==job&&ks.state==2&&ks.savedCrc==map.crc(),"save result fingerprint");
  client.startRecording();final ProtocolClient recordingClient=client;fails(()->recordingClient.applyKeyMap(finalMap));fails(()->recordingClient.defaultKeyMap());fails(()->recordingClient.upload(Score.golden(),new AtomicBoolean(),null));
  client.stopRecording();ProtocolClient.RecordingStatus s=client.recordingStatus();check(s.state==5&&s.count==2,"freeze");PerformanceRecording rec=new PerformanceRecording(s);AtomicBoolean cancel=new AtomicBoolean();fails(()->recordingClient.downloadRecording(rec,(n,t)->cancel.set(true),cancel));check(rec.received==1,"partial download");
  client=new ProtocolClient(peer);client.hello();client.performanceCapabilities();client.downloadRecording(rec,null,new AtomicBoolean());check(rec.received==2,"reconnect resume");Score score=new MidiFile(rec.midi()).convert(-1,-1,0,-1,false);check(score.notes.size()==2&&score.notes.get(0).timbre==0&&score.notes.get(1).timbre==15,"same pitch tone round trip");
  client.clearRecording(s.id);check(client.recordingStatus().count==0,"clear");
  for(int count:new int[]{16,36,4096}){PerformanceRecording r=fixture(count,count==36,false);byte[] midi=r.midi();Sequence independent=MidiSystem.getSequence(new ByteArrayInputStream(midi));check(independent.getTracks().length==37,"standard SMF parse");Score round=new MidiFile(midi).convert(-1,-1,0,-1,false);check(round.notes.size()==count,"all records retained");for(int k=0;k<count;k++){Score.Note n=round.notes.get(k);int p=k*12;check(n.start==Wire.u32(r.data,p)&&n.duration==Wire.u32(r.data,p+4)&&n.pitch==(r.data[p+8]&255)&&n.velocity==(r.data[p+9]&255)&&n.timbre==(r.data[p+10]&255),"onset roundtrip "+k);}if(count==36){check(round.polyphony==36,"full capture over 16 voices");fails(()->round.validate(new ProtocolClient.Capabilities(4096,16,21,108,5,9600,3600000)));}}
  PerformanceRecording longRec=fixture(1,false,true);check(MidiSystem.getSequence(new ByteArrayInputStream(longRec.midi()))!=null,"long note exports");fails(()->new MidiFile(longRec.midi()).convert(-1,-1,0,-1,false));
  PerformanceRecording shortRec=fixture(2,true,false);shortRec.data[11]=0;shortRec.data[23]=0;Wire.put32(shortRec.data,4,1);Wire.put32(shortRec.data,16,1);byte[] newStatus=new byte[20];newStatus[1]=5;Wire.put16(newStatus,6,2);Wire.put32(newStatus,12,Wire.crc32(shortRec.data));PerformanceRecording sameTick=new PerformanceRecording(new ProtocolClient.RecordingStatus(newStatus));System.arraycopy(shortRec.data,0,sameTick.data,0,24);sameTick.received=2;check(new MidiFile(sameTick.midi()).convert(-1,-1,0,-1,false).notes.size()==2,"same ms repeats sorted");
  PerformanceRecording corrupt=fixture(1,false,false);corrupt.data[0]^=1;fails(()->corrupt.verify());fails(()->new KeyMap(new byte[72]));
  System.out.println("PASS performance Java: "+checks+" checks; mapping/record/retry/resume/SMF multiport/4096/limits; no phone or hardware");
 }
}
